UPDATE mod_opennfse_notas n SET n.cancelado_em = NULL, n.cancel_xml_path = NULL, n.cancel_codigo_motivo = NULL, n.cancel_motivo = NULL, n.cancel_descricao = NULL, n.cancel_erro = NULL WHERE n.status <> 'CANCELADA' AND n.cancelado_em IS NOT NULL AND EXISTS (SELECT 1 FROM mod_opennfse_notas_history h WHERE h.tipo_registro = 'CANCELAMENTO' AND h.invoiceid = n.invoiceid AND h.cancelado_em = n.cancelado_em AND h.chave_acesso IS NOT NULL AND h.chave_acesso <> '' AND h.chave_acesso <> COALESCE(n.chave_acesso, ''));
UPDATE mod_opennfse_notas n SET n.cancel_xml_path = NULL WHERE n.status <> 'CANCELADA' AND n.cancel_xml_path IS NOT NULL AND n.cancel_xml_path <> '' AND EXISTS (SELECT 1 FROM mod_opennfse_notas_history h WHERE h.tipo_registro = 'CANCELAMENTO' AND h.invoiceid = n.invoiceid AND h.cancel_xml_path = n.cancel_xml_path AND h.chave_acesso IS NOT NULL AND h.chave_acesso <> '' AND h.chave_acesso <> COALESCE(n.chave_acesso, ''));
UPDATE mod_opennfse_notas_history e INNER JOIN mod_opennfse_notas_history c ON c.invoiceid = e.invoiceid AND c.tipo_registro = 'CANCELAMENTO' AND c.cancelado_em = e.cancelado_em AND c.chave_acesso IS NOT NULL AND c.chave_acesso <> '' AND c.chave_acesso <> COALESCE(e.chave_acesso, '') SET e.cancelado_em = NULL, e.cancel_xml_path = NULL, e.cancel_codigo_motivo = NULL, e.cancel_motivo = NULL, e.cancel_descricao = NULL, e.cancel_erro = NULL WHERE e.tipo_registro = 'EMISSAO' AND e.cancelado_em IS NOT NULL;
UPDATE mod_opennfse_notas_history e INNER JOIN mod_opennfse_notas_history c ON c.invoiceid = e.invoiceid AND c.tipo_registro = 'CANCELAMENTO' AND c.cancel_xml_path = e.cancel_xml_path AND c.chave_acesso IS NOT NULL AND c.chave_acesso <> '' AND c.chave_acesso <> COALESCE(e.chave_acesso, '') SET e.cancel_xml_path = NULL WHERE e.tipo_registro = 'EMISSAO' AND e.cancel_xml_path IS NOT NULL AND e.cancel_xml_path <> '';
